function deliverToOutput(payload,source,autoOpen=false){let win=outputWindow;if((!win||win.isDestroyed())&&autoOpen)win=createOutputWindow();if(!win||win.isDestroyed())return false;const enriched={...payload,source};currentOutputProgram={payload:{...enriched},currentSec:Math.max(0,Number(payload.startAtSec)||0),durationSec:Math.max(0,Number(payload.audioDurationSec)||0),at:Date.now(),paused:false};const deliver=()=>{if(win&&!win.isDestroyed())win.webContents.send('output:story',enriched);};if(win.webContents.isLoading())win.webContents.once('did-finish-load',deliver);else deliver();if(outputNdi?.status?.().running)ensureNdiWindow();if(ndiWindow&&!ndiWindow.isDestroyed()){const sendNdi=()=>{if(ndiWindow&&!ndiWindow.isDestroyed())ndiWindow.webContents.send('output:story',enriched);};if(ndiWindow.webContents.isLoading())ndiWindow.webContents.once('did-finish-load',sendNdi);else sendNdi();}try{outputLan?.publishStory(enriched);}catch(e){logEvent('OUTPUT_LAN_STORY',e.message||e);}const kind=payload.mediaRole==='ad'?'ad':(payload.kind||'news');setOutputState({open:true,visible:win.isVisible(),source,kind,title:payload.title||''});return true;}
