async function pickOutputAsset(kind){const isMusic=kind==='music',r=await dialog.showOpenDialog({properties:['openFile'],filters:isMusic?[{name:'Música MP3',extensions:['mp3']}]:[{name:'Imagen vertical',extensions:['png','jpg','jpeg','webp']}]});if(r.canceled||!r.filePaths[0])return{ok:false};const src=r.filePaths[0],ext=path.extname(src)||(isMusic?'.mp3':'.png'),dir=path.join(dataDir,'assets');fs.mkdirSync(dir,{recursive:true});const prefix=isMusic?'background-music':'vertical-video-background';for(const name of fs.readdirSync(dir)){if(name.startsWith(prefix+'.'))try{fs.rmSync(path.join(dir,name),{force:true});}catch{}}const dest=path.join(dir,`${prefix}${ext}`);fs.copyFileSync(src,dest);const s=settingsStore.load();if(isMusic)s.visual.output.musicFile=dest;else s.visual.output.verticalVideoBackground=dest;settingsStore.save(s);const persisted=settingsStore.load(),persistedPath=String(isMusic?persisted.visual?.output?.musicFile:persisted.visual?.output?.verticalVideoBackground||'');if(persistedPath&&path.resolve(persistedPath)!==path.resolve(dest))try{fs.rmSync(dest,{force:true});}catch{}const design=enrichDesign(persisted.visual?.output||{});sendDesignLive();return{ok:true,path:persistedPath,url:fileUrl(persistedPath),design};}
function clearOutputAsset(kind){const s=settingsStore.load(),isMusic=kind==='music',old=isMusic?s.visual.output.musicFile:s.visual.output.verticalVideoBackground;if(isMusic)s.visual.output.musicFile='';else s.visual.output.verticalVideoBackground='';settingsStore.save(s);cleanupManagedAsset(old,'');sendDesignLive();return{ok:true,design:currentDesign()};}
ipcMain.handle('output:pickVerticalBackground',()=>pickOutputAsset('background'));ipcMain.handle('output:clearVerticalBackground',()=>clearOutputAsset('background'));ipcMain.handle('output:pickMusic',()=>pickOutputAsset('music'));ipcMain.handle('output:clearMusic',()=>clearOutputAsset('music'));

ipcMain.handle('canned:pickFolder',async()=>{const r=await dialog.showOpenDialog({properties:['openDirectory']});if(r.canceled||!r.filePaths[0])return{ok:false};const s=settingsStore.load();s.canned.folder=r.filePaths[0];settingsStore.save(s);canned.reset();return{ok:true,...canned.list(s.canned.folder)};});ipcMain.handle('canned:list',()=>canned.list(settingsStore.load().canned?.folder||''));ipcMain.handle('canned:pickAdsFolder',async()=>{const r=await dialog.showOpenDialog({properties:['openDirectory']});if(r.canceled||!r.filePaths[0])return{ok:false};const s=settingsStore.load();s.canned.adsFolder=r.filePaths[0];s.canned.insertAdAfterContent=true;settingsStore.save(s);ads.reset();return{ok:true,...ads.list(s.canned.adsFolder)};});ipcMain.handle('canned:listAds',()=>ads.list(settingsStore.load().canned?.adsFolder||''));ipcMain.handle('canned:launchNow',()=>automation.requestCannedNow());

ipcMain.handle('output:monitorFrame',()=>captureOutputMonitorFrame());ipcMain.handle('output:benchmarkQuiesce',()=>quiesceOutputForBenchmark());ipcMain.handle('output:benchmarkRestore',()=>restoreOutputAfterBenchmark());ipcMain.handle('output:open',()=>{createOutputWindow(true);return{ok:true,state:{...outputState}};});ipcMain.handle('output:close',async()=>{if(!outputReady())return{ok:true,alreadyClosed:true,state:{...outputState}};outputWindow.hide();setOutputState({open:true,visible:false});return{ok:true,hidden:true,state:{...outputState}};});ipcMain.handle('output:status',()=>({...outputState,monitorAudio:monitorAudioEnabled,lan:outputLan?.status?.()||null,ndi:outputNdi?.status?.()||null}));ipcMain.handle('output:monitorAudio',(_,enabled)=>{monitorAudioEnabled=enabled===true;syncOutputAudioMute();return{ok:true,enabled:monitorAudioEnabled,state:{...outputState}};});ipcMain.handle('output:lanStatus',()=>outputLan?.status?.()||{enabled:false,error:'Servidor LAN no iniciado'});ipcMain.handle('output:lanEnsure',async()=>outputLan?outputLan.ensureRunning():{enabled:false,error:'Servidor LAN no iniciado'});ipcMain.handle('output:lanConfigure',async(_,p={})=>outputLan?outputLan.configure(p):{enabled:false,error:'Servidor LAN no iniciado'});ipcMain.handle('output:ndiStatus',()=>outputNdi?.status?.()||{enabled:false,running:false,error:'Salida NDI no iniciada'});ipcMain.handle('output:ndiConfigure',async(_,p={})=>{if(!outputNdi)return{enabled:false,running:false,error:'Salida NDI no iniciada'};const st=await outputNdi.configure(p);if(st.running)ensureNdiWindow();else destroyNdiWindow();return outputNdi.status();});ipcMain.handle('output:ndiWebsite',async()=>{await shell.openExternal('https://ndi.video/');return{ok:true};});ipcMain.on('output:ndiAudio',(event,p={})=>{if(!outputNdi?.status?.().running||!ndiWindow||ndiWindow.isDestroyed()||event.sender!==ndiWindow.webContents)return;try{const raw=p.data;let b;if(Buffer.isBuffer(raw))b=raw;else if(raw instanceof ArrayBuffer)b=Buffer.from(raw);else if(ArrayBuffer.isView(raw))b=Buffer.from(raw.buffer,raw.byteOffset,raw.byteLength);else return;outputNdi.sendAudio(b,Math.max(8000,Math.min(192000,Number(p.sampleRate)||48000)),Math.max(1,Math.min(8,Number(p.channels)||2)),Math.max(1,Math.min(8192,Number(p.samples)||0)));}catch(e){logEvent('OUTPUT_NDI_AUDIO',e?.message||e);}});ipcMain.handle('output:manualSend',async(_,p)=>{const a=automation.getState();if(a.emission.running){const r=await dialog.showMessageBox(controlWindow,{type:'warning',buttons:['Cancelar','Emitir ahora'],defaultId:0,cancelId:0,title:'Emisión automática activa',message:'La emisión automática está activa.',detail:'Si continúas, la emisión automática se pausará y esta nota tomará el Output.'});if(r.response!==1)return{ok:false,cancelled:true};automation.interruptForManual();}const ok=deliverToOutput({...p,kind:'news'},'manual',true);return{ok,source:'manual'};});ipcMain.on('output:control',(_,action)=>controlOutput(action));ipcMain.on('output:playback',(_,event)=>{try{outputLan?.updateMasterPlayback(event);}catch{}if(currentOutputProgram&&event?.source===currentOutputProgram.payload?.source){if(event?.type==='progress'){currentOutputProgram.currentSec=Math.max(0,Number(event.currentSec)||0);currentOutputProgram.durationSec=Math.max(0,Number(event.durationSec)||currentOutputProgram.durationSec||0);currentOutputProgram.at=Date.now();}else if(event?.type==='ended'&&currentOutputProgram.durationSec>0){currentOutputProgram.currentSec=currentOutputProgram.durationSec;currentOutputProgram.at=Date.now();currentOutputProgram.paused=true;}}automation.outputPlayback(event);if(event?.source==='manual'&&['ended','error'].includes(String(event?.type||''))){currentOutputProgram=null;setOutputState({source:'none',kind:'none',title:''});controlOutput('stop');}});ipcMain.on('output:designPreview',(_,design)=>{const merged=enrichDesign({...settingsStore.load().visual.output,...design});if(outputReady())outputWindow.webContents.send('output:design',merged);if(ndiWindow&&!ndiWindow.isDestroyed())ndiWindow.webContents.send('output:design',merged);try{outputLan?.publishDesign(merged);}catch{}if(outputReady()&&design?.format&&design.format!==outputState.format)applyOutputWindowFormat(design.format,true);if(ndiWindow&&!ndiWindow.isDestroyed()&&design?.format)applyNdiWindowFormat(design.format);});

